use bhoo::*;
mod fixture {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_adapter_view_flipper.rs"));}
mod item {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_adapter_flipper_item.rs"));}
fn setup()->(Ui,android_xml::LayoutState){let mut state=android_xml::LayoutState::default();state.set_list_adapter("adapter_flipper",vec!["First".into(),"Second".into(),"Third".into()],None,None).unwrap();state.set_list_item_template("adapter_flipper",Some(android_xml::ListItemTemplate{row:&item::LAYOUT,text_id:"flip_title"})).unwrap();(Ui::default(),state)}
fn draw(ui:&mut Ui,state:&mut android_xml::LayoutState,time:f64)->Vec<DrawCommand>{let b=Rect{x:0.,y:0.,width:300.,height:160.};ui.frame(Input{time,..Input::default()},b,0.,|f|{fixture::LAYOUT.render(f,b,state);})}
#[test] fn adapter_flipper_advances_crossfades_and_wraps(){let(mut ui,mut state)=setup();let first=draw(&mut ui,&mut state,1.);assert!(first.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="First")));assert_eq!(ui.next_wakeup(),Some(3.5));draw(&mut ui,&mut state,3.5);assert_eq!(state.displayed_children["adapter_flipper"],1);let middle=draw(&mut ui,&mut state,3.6);let names:Vec<_>=middle.iter().filter_map(|c|match c{DrawCommand::Text{text,color,..} if text.as_ref()=="First"||text.as_ref()=="Second"=>Some((text.as_ref(),color.3)),_=>None}).collect();assert_eq!(names.len(),2);assert!(names.iter().all(|(_,alpha)|*alpha>0&&*alpha<255));draw(&mut ui,&mut state,6.);draw(&mut ui,&mut state,8.5);assert_eq!(state.displayed_children["adapter_flipper"],0);}
#[test] fn manual_step_resets_timer_and_stopping_pauses(){let(mut ui,mut state)=setup();draw(&mut ui,&mut state,1.);assert!(state.adapter_flipper_step("adapter_flipper",-1));draw(&mut ui,&mut state,2.);assert_eq!(state.displayed_children["adapter_flipper"],2);assert_eq!(ui.next_wakeup(),Some(4.5));state.flipper_running.insert("adapter_flipper".into(),false);draw(&mut ui,&mut state,3.);draw(&mut ui,&mut state,10.);assert_eq!(state.displayed_children["adapter_flipper"],2);assert_eq!(ui.next_wakeup(),None);}
#[test] fn empty_adapter_has_no_timer_and_step_is_safe(){let(mut ui,mut state)=setup();state.list_items.insert("adapter_flipper".into(),vec![]);draw(&mut ui,&mut state,1.);assert_eq!(ui.next_wakeup(),None);assert!(!state.adapter_flipper_step("adapter_flipper",1));}
#[test] fn tapping_visible_adapter_item_reports_position(){let(mut ui,mut state)=setup();draw(&mut ui,&mut state,1.);let b=Rect{x:0.,y:0.,width:300.,height:160.};let p=Some([150.,80.]);ui.frame(Input{pointer:p,pressed:true,time:1.1,..Input::default()},b,0.,|f|{fixture::LAYOUT.render(f,b,&mut state);});let mut action=None;ui.frame(Input{pointer:p,released:true,time:1.11,..Input::default()},b,0.,|f|action=fixture::LAYOUT.render(f,b,&mut state));assert_eq!(action,Some("adapter_flipper"));assert_eq!(state.adapter_flipper_clicked["adapter_flipper"],0);}
#[test] fn reduced_motion_switches_without_crossfade(){let(mut ui,mut state)=setup();ui.motion_preference=MotionPreference::Reduced;draw(&mut ui,&mut state,1.);draw(&mut ui,&mut state,3.5);let commands=draw(&mut ui,&mut state,3.55);assert!(!commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="First")));assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="Second")));}
#[test] fn data_changes_keep_valid_position_and_reset_out_of_range(){let(mut ui,mut state)=setup();state.flipper_running.insert("adapter_flipper".into(),false);draw(&mut ui,&mut state,1.);assert!(state.adapter_flipper_step("adapter_flipper",1));draw(&mut ui,&mut state,1.3);state.set_list_adapter("adapter_flipper",vec!["Third".into(),"Second".into(),"First".into()],Some(vec![30,20,10]),None).unwrap();let commands=draw(&mut ui,&mut state,1.4);assert_eq!(state.displayed_children["adapter_flipper"],1);assert!(commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="Second")));assert!(!commands.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="Third")));state.set_list_adapter("adapter_flipper",vec!["Only".into()],Some(vec![30]),None).unwrap();draw(&mut ui,&mut state,1.5);assert_eq!(state.displayed_children["adapter_flipper"],0);}
#[test] fn adapter_replacement_during_press_does_not_click_replacement(){let(mut ui,mut state)=setup();state.flipper_running.insert("adapter_flipper".into(),false);draw(&mut ui,&mut state,1.);let b=Rect{x:0.,y:0.,width:300.,height:160.};let p=Some([100.,80.]);ui.frame(Input{pointer:p,pressed:true,time:1.1,..Input::default()},b,0.,|f|{fixture::LAYOUT.render(f,b,&mut state);});state.set_list_adapter("adapter_flipper",vec!["Replacement".into(),"Second".into()],None,None).unwrap();let mut action=None;ui.frame(Input{pointer:p,released:true,time:1.2,..Input::default()},b,0.,|f|action=fixture::LAYOUT.render(f,b,&mut state));assert_eq!(action,None);assert!(!state.adapter_flipper_clicked.contains_key("adapter_flipper"));}
#[test] fn host_driven_advance_suppresses_timer_without_clearing_started_state(){let(mut ui,mut state)=setup();draw(&mut ui,&mut state,1.);assert_eq!(ui.next_wakeup(),Some(3.5));state.adapter_flipper_advance_by_host("adapter_flipper");draw(&mut ui,&mut state,2.);assert_eq!(ui.next_wakeup(),None);assert_eq!(state.flipper_running["adapter_flipper"],true);draw(&mut ui,&mut state,12.);assert_eq!(state.displayed_children["adapter_flipper"],0);assert!(state.adapter_flipper_step("adapter_flipper",1));draw(&mut ui,&mut state,12.1);assert_eq!(state.displayed_children["adapter_flipper"],1);assert_eq!(ui.next_wakeup(),None);}
mod custom {include!(concat!(env!("CARGO_MANIFEST_DIR"),"/../../../apps/bhoo-web/src/android_adapter_view_flipper_custom.rs"));}
#[test] fn custom_xml_object_animators_change_crossfade_duration(){let(mut ui,mut state)=setup();state.flipper_running.insert("adapter_flipper".into(),false);let b=Rect{x:0.,y:0.,width:300.,height:160.};let draw=|ui:&mut Ui,state:&mut android_xml::LayoutState,time|ui.frame(Input{time,..Input::default()},b,0.,|f|{custom::LAYOUT.render(f,b,state);});draw(&mut ui,&mut state,1.);state.adapter_flipper_step("adapter_flipper",1);draw(&mut ui,&mut state,1.1);let middle=draw(&mut ui,&mut state,1.5);let colors:Vec<_>=middle.iter().filter_map(|c|match c{DrawCommand::Text{text,color,..} if text.as_ref()=="First"||text.as_ref()=="Second"=>Some(color.3),_=>None}).collect();assert_eq!(colors.len(),2);assert!(colors.iter().all(|alpha|(125..=130).contains(alpha)));let done=draw(&mut ui,&mut state,2.0);assert!(!done.iter().any(|c|matches!(c,DrawCommand::Text{text,..} if text.as_ref()=="First")));}
#[test] fn incoming_animator_retains_nonunit_final_alpha(){static PARTIAL:android_xml::Node=android_xml::Node{animation_in:Some(android_xml::AlphaAnimation{from:0.,to:0.5,duration:0.2,start_offset:0.0,linear:true}),..fixture::LAYOUT};let(mut ui,mut state)=setup();state.flipper_running.insert("adapter_flipper".into(),false);let b=Rect{x:0.,y:0.,width:300.,height:160.};let draw=|ui:&mut Ui,state:&mut android_xml::LayoutState,time|ui.frame(Input{time,..Input::default()},b,0.,|f|{PARTIAL.render(f,b,state);});draw(&mut ui,&mut state,1.);state.adapter_flipper_step("adapter_flipper",1);draw(&mut ui,&mut state,1.1);let done=draw(&mut ui,&mut state,1.4);let alpha=done.iter().find_map(|c|match c{DrawCommand::Text{text,color,..} if text.as_ref()=="Second"=>Some(color.3),_=>None}).unwrap();assert!((126..=129).contains(&alpha));}
#[test] fn custom_animator_set_moves_both_rows_during_crossfade(){let(mut ui,mut state)=setup();state.flipper_running.insert("adapter_flipper".into(),false);let b=Rect{x:0.,y:0.,width:300.,height:160.};let draw=|ui:&mut Ui,state:&mut android_xml::LayoutState,time|ui.frame(Input{time,..Input::default()},b,0.,|f|{custom::LAYOUT.render(f,b,state);});draw(&mut ui,&mut state,1.);state.adapter_flipper_step("adapter_flipper",1);draw(&mut ui,&mut state,1.1);let before=draw(&mut ui,&mut state,1.1);let base_y=before.iter().find_map(|c|match c{DrawCommand::Text{text,bounds,..} if text.as_ref()=="First"=>Some(bounds.y),_=>None}).unwrap();let middle=draw(&mut ui,&mut state,1.5);let y=|label:&str|middle.iter().find_map(|c|match c{DrawCommand::Text{text,bounds,..} if text.as_ref()==label=>Some(bounds.y),_=>None}).unwrap();assert!((y("First")-base_y).abs()<0.01);assert!((y("Second")-base_y).abs()<0.01);let x=|label:&str|middle.iter().find_map(|c|match c{DrawCommand::Text{text,bounds,..} if text.as_ref()==label=>Some(bounds.x),_=>None}).unwrap();assert!((x("First")+36.).abs()<0.01);assert!((x("Second")-36.).abs()<0.01);}
#[test] fn xml_loop_views_false_still_wraps_like_android_adapter_view_flipper(){
    use bhoo::android_xml::RelativeRule;
    static FALSE:android_xml::Node=android_xml::Node{relative_rules:&[RelativeRule{kind:137,anchor:"false"}],..fixture::LAYOUT};
    let(mut ui,mut state)=setup();state.flipper_running.insert("adapter_flipper".into(),false);let b=Rect{x:0.,y:0.,width:300.,height:160.};ui.frame(Input::default(),b,0.,|f|{FALSE.render(f,b,&mut state);});
    assert!(state.adapter_flipper_step("adapter_flipper",-1));assert_eq!(state.displayed_children["adapter_flipper"],2);
    ui.frame(Input{time:1.,..Input::default()},b,0.,|f|{FALSE.render(f,b,&mut state);});assert!(state.adapter_flipper_step("adapter_flipper",1));assert_eq!(state.displayed_children["adapter_flipper"],0);
}
